package com.endra.spell
import org.junit.Assert.*
import org.junit.Test
import java.time.LocalDate
import kotlin.random.Random
class CheckpointBTest {
 private class IO:SnapshotIO{var value:String?=null;var fail=false;override fun read()=value;override fun backup()=value;override fun write(value:String){check(!fail);this.value=value}}
 private val io=IO();private val store=FoundationStore(io,{emptyMap<String,Any>()},{LocalDate.parse("2026-10-06")});private val id by lazy { store.addLearner("Import Test") }
 private fun row(s:String,heart:Boolean=false)=ReviewWord(text=s,category=if(heart)WordCategory.HEART else WordCategory.SPELLING)
 private fun line(s:String,x:Float,y:Float)=RecognizedLine(s,x,y,x+150,y+30)
 @Test fun spatialHeadersOverrideSideAndReadingOrder(){val r=WorksheetClassifier.classify(listOf(line("apple",650f,200f),line("Heart Words",50f,50f),line("said",50f,200f),line("Spelling Words",650f,50f)),1000f,1000f);assertEquals(WordCategory.HEART,r.rows.first{it.text=="said"}.category);assertEquals(WordCategory.SPELLING,r.rows.first{it.text=="apple"}.category)}
 @Test fun stackedSectionsUseNearestHeading(){val r=WorksheetClassifier.classify(listOf(line("Spelling Words",100f,50f),line("apple",100f,100f),line("Heart Words",100f,300f),line("said",100f,350f)),1000f,1000f);assertEquals(listOf(WordCategory.SPELLING,WordCategory.HEART),r.rows.map{it.category})}
 @Test fun unlabelledClippedAndBlankScansWarn(){val r=WorksheetClassifier.classify(listOf(line("1. apple",0f,100f),line("the",600f,150f)),1000f,1000f);assertEquals("apple",r.rows[0].text);assertTrue(r.rows.all{it.uncertain});assertTrue(r.warnings.size>=3);assertTrue(WorksheetClassifier.classify(emptyList(),1000f,1000f).rows.isEmpty())}
 @Test fun actualWordsLikeReadAreNotDropped(){val r=WorksheetClassifier.classify(listOf(line("read",50f,100f),line("write",50f,150f),line("practice",50f,200f)),1000f,1000f);assertEquals(listOf("read","write","practice"),r.rows.map{it.text})}
 @Test fun reviewEditsMovesDeletesAddsAndCancellationDoNotWrite(){id;val before=store.snapshot().toString();var rows=listOf(row("aple"),row("said"),row("delete"));rows=rows.dropLast(1).map{if(it.text=="aple")it.copy(text="apple")else it.copy(category=WordCategory.HEART)}+row("added");assertEquals(before,store.snapshot().toString());store.importReviewed(id,store.currentWeek(id),rows);assertEquals(listOf("apple","added"),store.words(id,false));assertEquals(listOf("said"),store.words(id,true))}
 @Test fun duplicateHeartKeepsIdHistoryAndRecordingLink(){store.save(id,true,"said");store.record(id,true,"said","sad");store.extraPractice(id,"said",true);val before=store.snapshot().getJSONArray("learners").getJSONObject(0).getJSONArray("words").toString();val rows=listOf(row("said",true),row(" SAID ",true),row("said"));assertEquals(1,WorksheetClassifier.duplicateKeys(rows).size);assertEquals(1,store.importReviewed(id,store.currentWeek(id),rows));assertEquals(before,store.snapshot().getJSONArray("learners").getJSONObject(0).getJSONArray("words").toString());assertEquals(1,store.events(id).length());assertTrue(store.progress(id,"said").extraPractice)}
 @Test fun archivedSpellingCanRecurWithoutNewWordIdentity(){store.save(id,false,"apple");val words=store.snapshot().getJSONArray("learners").getJSONObject(0).getJSONArray("words").toString();store.startNewWeek(id);store.importReviewed(id,store.currentWeek(id),listOf(row("apple")));assertEquals(words,store.snapshot().getJSONArray("learners").getJSONObject(0).getJSONArray("words").toString());assertEquals(1,store.history(id).length())}
 @Test fun failedAtomicImportCanRetry(){val week=store.currentWeek(id);val before=io.value;io.fail=true;assertThrows(Exception::class.java){store.importReviewed(id,week,listOf(row("apple"),row("said",true)))};assertEquals(before,io.value);io.fail=false;assertEquals(2,store.importReviewed(id,week,listOf(row("apple"),row("said",true))))}
 @Test fun blankAndStaleWeekCannotPartiallyCommit(){val week=store.currentWeek(id);val before=io.value;assertThrows(Exception::class.java){store.importReviewed(id,week,listOf(row("good"),row(" ")))};assertEquals(before,io.value);store.startNewWeek(id);val after=io.value;assertThrows(Exception::class.java){store.importReviewed(id,week,listOf(row("stale")))};assertEquals(after,io.value)}
 @Test fun archivedAndMissingLearnerRejectImport(){val week=store.currentWeek(id);store.archive(id,true);val before=io.value;assertThrows(Exception::class.java){store.importReviewed(id,week,listOf(row("archived")))};assertThrows(Exception::class.java){store.importReviewed("missing",week,listOf(row("missing")))};assertEquals(before,io.value)}
 @Test fun shuffleDoesNotChangeTeacherOrderOrOtherLearner(){val a=id;val b=store.addLearner("Second");store.save(a,false,"one\ntwo\nthree");val words=store.practiceWords(a);repeat(10){val shuffled=PracticeEngine.shuffle(words,Random(it));assertEquals(words.toSet(),shuffled.toSet());assertNotEquals(words,shuffled)};assertEquals(listOf("one","two","three"),store.words(a,false));assertTrue(store.words(b,false).isEmpty())}
 @Test fun hardPoolIncludesHistoricalReviewAndManualExtra(){store.save(id,false,"review\nextra\nordinary");repeat(2){store.record(id,false,"review","wrong")};store.extraPractice(id,"extra",true);store.startNewWeek(id);assertEquals(setOf("review","extra"),PracticeEngine.hard(store.practiceWords(id)).map{it.text}.toSet());store.extraPractice(id,"extra",false);assertEquals(listOf("review"),PracticeEngine.hard(store.practiceWords(id)).map{it.text})}
 @Test fun weightedSmartAvoidsRepeatsAndHandlesSmallPools(){val words=listOf(PracticeWord("review",false,needsReview=true),PracticeWord("miss",false,recentMiss=true),PracticeWord("extra",false,extraPractice=true),PracticeWord("new",false),PracticeWord("ordinary",false,correct=5,studied=5));assertEquals(listOf(8,6,4,2,1),words.map{it.weight});val counts=mutableMapOf<String,Int>();repeat(300){val list=PracticeEngine.smart(words,Random(it));assertTrue(list.zipWithNext().all{it.first.text!=it.second.text});list.forEach{counts[it.text]=(counts[it.text]?:0)+1}};assertTrue(counts.getValue("review")>counts.getValue("ordinary")*2);assertTrue(PracticeEngine.smart(emptyList()).isEmpty());assertEquals(1,PracticeEngine.smart(words.take(1)).distinct().size)}
 @Test fun breakdownRequiresApprovalAndStudyNeverCountsMastery(){store.save(id,false,"apple");store.breakdown(id,"apple","ap · ple",false);assertNull(store.practiceWords(id).single().breakdown);store.breakdown(id,"apple","ap · ple",true);assertEquals("ap · ple",store.practiceWords(id).single().breakdown);val progress=store.progress(id,"apple");repeat(30){store.record(id,false,"apple",null)};assertEquals(progress,store.progress(id,"apple"));assertEquals(0,store.practiceWords(id).single().correct);store.breakdown(id,"apple","",true);assertNull(store.practiceWords(id).single().breakdown)}
}
